// signInLabel keeps every provider button named, so a missing Label never leaves an icon-only button.
func signInLabel(pr SignInProvider) string {
	if pr.Label != "" {
		return pr.Label
	}
	switch pr.Name {
	case "google":
		return "Google"
	case "github":
		return "GitHub"
	}
	return pr.Name
}

func signInGlyph(pr SignInProvider) templ.Component {
	if pr.Icon != nil {
		return pr.Icon
	}
	switch pr.Name {
	case "google":
		return signInGoogle()
	case "github":
		return signInGitHub()
	}
	return nil
}

